// dice-roller-bd -- UI. Depends on window.DiceLogic and window.I18N.
// All shipped sources stay pure ASCII: Bengali strings live in js/i18n.js
// as \uXXXX escapes (generated by tools/gen_i18n.py).
(function () {
  'use strict';
  var L = window.DiceLogic;
  var I18N = window.I18N;
  var STORE_KEY = 'dice-roller-bd:v1';
  var MAX_HISTORY = 30;
  var MAX_PRESETS = 50;

  var BUILTINS = [
    { id: 'builtin-attack', name: 'Attack Roll', notation: 'd20+5', builtin: true },
    { id: 'builtin-fireball', name: 'Fireball', notation: '8d6', builtin: true },
    { id: 'builtin-ability', name: 'Ability Score', notation: '4d6dl1', builtin: true },
    { id: 'builtin-initiative', name: 'Initiative', notation: 'd20+2', builtin: true }
  ];

  var state = {
    lang: 'en',
    pool: {},
    presets: [],   // user presets only; built-ins are constant
    history: [],   // {notation, total, faces, at}
    lastRoll: null // {notation, result}
  };
  L.VALID_SIDES.forEach(function (s) { state.pool['d' + s] = 0; });

  function $(id) { return document.getElementById(id); }
  function t(key) { return (I18N[state.lang] && I18N[state.lang][key]) || I18N.en[key] || key; }
  function bnDigits(str) {
    if (state.lang !== 'bn') return String(str);
    var digits = I18N.bn.bnDigits; // Bengali digit string, from escaped i18n.js
    return String(str).replace(/[0-9]/g, function (d) { return digits[parseInt(d, 10)]; });
  }
  function fmt(n) { return bnDigits(n); }

  function load() {
    try {
      var raw = localStorage.getItem(STORE_KEY);
      if (!raw) return;
      var d = JSON.parse(raw);
      if (d.lang === 'en' || d.lang === 'bn') state.lang = d.lang;
      if (Array.isArray(d.presets)) state.presets = d.presets.filter(function (p) {
        return p && typeof p.name === 'string' && typeof p.notation === 'string' && L.parseNotation(p.notation).ok;
      }).slice(0, MAX_PRESETS);
      if (Array.isArray(d.history)) state.history = d.history.filter(function (h) {
        return h && typeof h.notation === 'string' && typeof h.total === 'number' && Array.isArray(h.faces);
      }).slice(0, MAX_HISTORY);
    } catch (e) { /* corrupted storage: start empty */ }
  }
  function save() {
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify({
        lang: state.lang, presets: state.presets, history: state.history
      }));
    } catch (e) { /* storage full/blocked: app still works in-memory */ }
  }

  function poolCount() {
    var n = 0;
    Object.keys(state.pool).forEach(function (k) { n += state.pool[k]; });
    return n;
  }
  function poolNotation() {
    var parts = [];
    L.VALID_SIDES.forEach(function (s) {
      var c = state.pool['d' + s];
      if (c) parts.push(c + 'd' + s);
    });
    var mod = parseInt($('modifierInput').value, 10);
    if (isNaN(mod)) mod = 0;
    var s = parts.join('+');
    if (mod > 0) s += '+' + mod;
    if (mod < 0) s += String(mod);
    return s;
  }

  function renderQuickDice() {
    var box = $('quickDice');
    box.innerHTML = '';
    L.VALID_SIDES.forEach(function (sides) {
      var card = document.createElement('div');
      card.className = 'die-card';
      card.innerHTML = '<div class="die-name">d' + sides + '</div>' +
        '<div class="die-count" data-count-for="d' + sides + '">x ' + fmt(state.pool['d' + sides]) + '</div>' +
        '<div class="stepper">' +
        '<button type="button" data-die="d' + sides + '" data-delta="-1" aria-label="remove d' + sides + '">-</button>' +
        '<button type="button" data-die="d' + sides + '" data-delta="1" aria-label="add d' + sides + '">+</button>' +
        '</div>';
      box.appendChild(card);
    });
    box.querySelectorAll('button[data-die]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var key = btn.getAttribute('data-die');
        var d = parseInt(btn.getAttribute('data-delta'), 10);
        state.pool[key] = Math.max(0, Math.min(L.MAX_COUNT, state.pool[key] + d));
        renderPool();
        renderQuickDice();
      });
    });
  }

  function renderPool() {
    var list = $('poolList');
    list.innerHTML = '';
    var empty = poolCount() === 0;
    $('poolEmpty').hidden = !empty;
    $('poolEmpty').textContent = empty ? t('poolEmpty') : '';
    L.VALID_SIDES.forEach(function (sides) {
      var c = state.pool['d' + sides];
      if (!c) return;
      var chip = document.createElement('span');
      chip.className = 'pool-chip';
      chip.textContent = c + 'd' + sides;
      list.appendChild(chip);
    });
    $('rollPoolBtn').disabled = empty;
  }

  function recordHistory(notation, result) {
    state.history.unshift({
      notation: notation, total: result.total,
      faces: result.faces.map(function (f) { return { sides: f.sides, value: f.value, kept: f.kept }; }),
      at: new Date().toISOString()
    });
    state.history = state.history.slice(0, MAX_HISTORY);
    save();
    renderHistory();
  }

  function showResult(notation, result, modeIgnored) {
    state.lastRoll = { notation: notation, result: result };
    $('resultEmpty').hidden = true;
    $('resultContent').hidden = false;
    $('resultNotation').textContent = notation;
    var facesBox = $('dieFaces');
    facesBox.innerHTML = '';
    var crit = L.critFor(result);
    result.faces.forEach(function (f) {
      var el = document.createElement('span');
      el.className = 'die-face' + (f.kept ? '' : ' dropped');
      if (crit === 'crit' && f.kept && f.sides === 20 && f.value === 20) el.classList.add('crit-face');
      el.appendChild(document.createTextNode(fmt(f.value)));
      var lab = document.createElement('span');
      lab.className = 'die-sides';
      lab.textContent = 'd' + f.sides;
      el.appendChild(lab);
      if (!f.kept) el.title = t('dropped');
      facesBox.appendChild(el);
    });
    $('resultTotal').textContent = fmt(result.total);
    $('resultRange').textContent = fmt(result.min) + ' - ' + fmt(result.max);
    var badge = $('critBadge');
    if (crit === 'crit') { badge.hidden = false; badge.textContent = t('crit'); }
    else if (crit === 'fumble') { badge.hidden = false; badge.textContent = t('fumble'); }
    else badge.hidden = true;
    $('modeIgnored').hidden = !modeIgnored;
    if (modeIgnored) $('modeIgnored').textContent = t('modeIgnored');
  }

  function rollPoolNow(rng) {
    rng = rng || Math.random;
    if (poolCount() === 0) {
      var err = $('notationError');
      err.hidden = false;
      err.textContent = t('poolEmpty');
      return null;
    }
    var mod = parseInt($('modifierInput').value, 10);
    if (isNaN(mod)) mod = 0;
    mod = Math.max(-L.MAX_MOD, Math.min(L.MAX_MOD, mod));
    var mode = $('modeSelect').value;
    var result = L.rollPool(state.pool, mod, mode, rng);
    var notation = poolNotation(); // plain notation: history/import must re-parse it
    $('notationError').hidden = true;
    showResult(notation, result, result.modeIgnored);
    recordHistory(notation, result);
    return result;
  }

  function rollNotationNow(rng, forced) {
    rng = rng || Math.random;
    var raw = forced !== undefined ? forced : $('notationInput').value;
    var parsed = L.parseNotation(raw);
    var err = $('notationError');
    if (!parsed.ok) {
      err.hidden = false;
      err.textContent = t('err_' + parsed.error);
      return null;
    }
    err.hidden = true;
    var result = L.rollNotation(parsed, rng);
    var notation = L.formatNotation(parsed);
    showResult(notation, result, false);
    recordHistory(notation, result);
    return result;
  }

  function renderPresets() {
    var list = $('presetList');
    list.innerHTML = '';
    var all = BUILTINS.concat(state.presets);
    $('presetsEmpty').hidden = true; // built-ins always exist, so this never shows
    $('presetsEmpty').textContent = t('presetsEmpty');
    all.forEach(function (p) {
      var card = document.createElement('div');
      card.className = 'preset-card';
      var left = document.createElement('div');
      var nameEl = document.createElement('span');
      nameEl.className = 'p-name';
      nameEl.textContent = p.name + ' ';
      left.appendChild(nameEl);
      if (p.builtin) {
        var b = document.createElement('span');
        b.className = 'badge';
        b.textContent = t('builtinLabel');
        left.appendChild(b);
        left.appendChild(document.createTextNode(' '));
      }
      var notEl = document.createElement('span');
      notEl.className = 'p-notation';
      notEl.textContent = p.notation;
      left.appendChild(notEl);
      var actions = document.createElement('div');
      actions.className = 'row';
      var rollBtn = document.createElement('button');
      rollBtn.type = 'button';
      rollBtn.className = 'btn primary';
      rollBtn.textContent = t('loadBtn');
      rollBtn.addEventListener('click', function () {
        switchTab('roll');
        $('notationInput').value = p.notation;
        rollNotationNow();
      });
      actions.appendChild(rollBtn);
      if (!p.builtin) {
        var delBtn = document.createElement('button');
        delBtn.type = 'button';
        delBtn.className = 'btn';
        delBtn.textContent = t('deleteBtn');
        delBtn.addEventListener('click', function () {
          state.presets = state.presets.filter(function (x) { return x.id !== p.id; });
          save();
          renderPresets();
        });
        actions.appendChild(delBtn);
      }
      card.appendChild(left);
      card.appendChild(actions);
      list.appendChild(card);
    });
  }

  function renderHistory() {
    var list = $('historyList');
    list.innerHTML = '';
    $('historyEmpty').hidden = state.history.length !== 0;
    $('historyEmpty').textContent = t('historyEmpty');
    var stats = L.historyStats(state.history);
    $('statRolls').textContent = fmt(stats.count);
    $('statAvg').textContent = stats.count ? fmt(stats.avgTotal.toFixed(1)) : t('statsNone');
    $('statCommon').textContent = stats.mostCommonTotal === null ? t('statsNone') : fmt(stats.mostCommonTotal);
    var diceParts = Object.keys(stats.bySides).sort(function (a, b) {
      return parseInt(a.slice(1), 10) - parseInt(b.slice(1), 10);
    }).map(function (k) { return k + 'x' + fmt(stats.bySides[k]); });
    $('statDice').textContent = diceParts.length ? diceParts.join(', ') : t('statsNone');
    state.history.forEach(function (h) {
      var card = document.createElement('div');
      card.className = 'history-card';
      var left = document.createElement('div');
      var n = document.createElement('div');
      n.className = 'h-notation';
      n.textContent = h.notation;
      var faces = document.createElement('div');
      faces.className = 'h-faces';
      faces.textContent = h.faces.map(function (f) { return (f.kept ? '' : 'x') + fmt(f.value) + '(d' + f.sides + ')'; }).join(' ');
      var time = document.createElement('div');
      time.className = 'h-time';
      time.textContent = new Date(h.at).toLocaleString(state.lang === 'bn' ? 'bn-BD' : 'en-GB');
      left.appendChild(n);
      left.appendChild(faces);
      left.appendChild(time);
      var total = document.createElement('div');
      total.className = 'h-total';
      total.textContent = fmt(h.total);
      card.appendChild(left);
      card.appendChild(total);
      list.appendChild(card);
    });
  }

  function renderGuide() {
    var list = $('guideList');
    list.innerHTML = '';
    for (var i = 1; i <= 7; i++) {
      var li = document.createElement('li');
      li.textContent = t('guide_' + i);
      list.appendChild(li);
    }
  }

  function applyI18n() {
    document.querySelectorAll('[data-i18n]').forEach(function (el) {
      el.textContent = t(el.getAttribute('data-i18n'));
    });
    $('subtitle').textContent = t('subtitle');
    $('footerText').textContent = t('footer');
    $('langBtn').textContent = t('langBtn');
    document.documentElement.lang = state.lang === 'bn' ? 'bn' : 'en';
    $('resultEmpty').textContent = t('resultEmpty');
    $('notationInput').placeholder = t('notationPh');
    $('presetName').placeholder = t('presetNamePh');
    $('importText').placeholder = t('importPh');
    renderQuickDice();
    renderPool();
    renderPresets();
    renderHistory();
    renderGuide();
    // Re-render the last result so totals/faces use the new language's digits.
    if (state.lastRoll) showResult(state.lastRoll.notation, state.lastRoll.result, false);
  }

  function switchTab(name) {
    document.querySelectorAll('.tab').forEach(function (b) {
      b.classList.toggle('active', b.getAttribute('data-tab') === name);
    });
    ['roll', 'presets', 'history', 'guide'].forEach(function (n) {
      $('tab-' + n).hidden = n !== name;
    });
  }

  function exportPayload() {
    return JSON.stringify({
      app: 'dice-roller-bd', version: 1,
      presets: state.presets, history: state.history
    });
  }

  function importPayload(text) {
    var parsed;
    try { parsed = JSON.parse(text); }
    catch (e) { return { ok: false, error: 'bad-json' }; }
    var v = L.validateImport(parsed);
    if (!v.ok) return v;
    state.presets = parsed.presets;
    state.history = parsed.history.slice(0, MAX_HISTORY);
    save();
    renderPresets();
    renderHistory();
    return { ok: true };
  }

  function eraseAll() {
    state.presets = [];
    state.history = [];
    state.lastRoll = null;
    save();
    renderPresets();
    renderHistory();
    $('resultContent').hidden = true;
    $('resultEmpty').hidden = false;
  }

  // ---- wire up ----
  document.querySelectorAll('.tab').forEach(function (b) {
    b.addEventListener('click', function () { switchTab(b.getAttribute('data-tab')); });
  });
  $('langBtn').addEventListener('click', function () {
    state.lang = state.lang === 'en' ? 'bn' : 'en';
    save();
    applyI18n();
  });
  $('rollPoolBtn').addEventListener('click', function () { rollPoolNow(); });
  $('clearPoolBtn').addEventListener('click', function () {
    Object.keys(state.pool).forEach(function (k) { state.pool[k] = 0; });
    renderQuickDice();
    renderPool();
  });
  $('rollNotationBtn').addEventListener('click', function () { rollNotationNow(); });
  $('notationInput').addEventListener('keydown', function (e) {
    if (e.key === 'Enter') rollNotationNow();
  });
  $('savePresetBtn').addEventListener('click', function () {
    var need = $('savePresetNeed');
    var msg = $('savePresetMsg');
    need.hidden = true;
    msg.hidden = true;
    if (!state.lastRoll) {
      need.hidden = false;
      need.textContent = t('savePresetNeed');
      return;
    }
    var name = $('presetName').value.trim() || state.lastRoll.notation;
    state.presets.unshift({
      id: 'p' + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36),
      name: name.slice(0, 60), notation: state.lastRoll.notation
    });
    state.presets = state.presets.slice(0, MAX_PRESETS);
    $('presetName').value = '';
    save();
    renderPresets();
    msg.hidden = false;
    msg.textContent = t('savedMsg');
  });
  $('clearHistoryBtn').addEventListener('click', function () {
    state.history = [];
    save();
    renderHistory();
    var m = $('clearedMsg');
    m.hidden = false;
    m.textContent = t('clearedMsg');
  });
  $('exportBtn').addEventListener('click', function () {
    $('exportText').value = exportPayload();
  });
  $('importBtn').addEventListener('click', function () {
    var res = importPayload($('importText').value);
    $('importOk').hidden = true;
    $('importFail').hidden = true;
    if (res.ok) {
      $('importOk').hidden = false;
      $('importOk').textContent = t('importOk');
    } else {
      $('importFail').hidden = false;
      $('importFail').textContent = t('importFail') + res.error;
    }
  });
  $('eraseBtn').addEventListener('click', function () {
    if ($('eraseInput').value !== 'DELETE') {
      $('eraseWrong').hidden = false;
      $('eraseWrong').textContent = t('eraseWrong');
      return;
    }
    $('eraseWrong').hidden = true;
    eraseAll();
    $('eraseInput').value = '';
    $('erasedMsg').hidden = false;
    $('erasedMsg').textContent = t('erasedMsg');
  });

  load();
  applyI18n();

  // Test hooks (used by tests/smoke.js only).
  window.__drbd = {
    state: state,
    exportPayload: exportPayload,
    importPayload: importPayload,
    eraseAll: eraseAll,
    rollNotationWith: function (notation, values) {
      var i = 0;
      var rng = function () { return values[i++ % values.length]; };
      return rollNotationNow(rng, notation);
    },
    rollPoolWith: function (values) {
      var i = 0;
      var rng = function () { return values[i++ % values.length]; };
      return rollPoolNow(rng);
    }
  };
})();
